require_once __DIR__ . '/../includes/auth.php';require_role(['superadmin']);$rows=$pdo->query("SELECT l.*,a.username FROM audit_logs l LEFT JOIN accounts a ON a.id=l.actor_id ORDER BY l.created_at DESC LIMIT 300")->fetchAll();page_header('Audit Logs');?><h1>Audit Logs</h1><div class="table-wrap"><table><tr><th>Date</th><th>Actor</th><th>Action</th><th>Target</th><th>Details</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['username']??'System/deleted')?></td><td><?=e($r['action'])?></td><td><?=e($r['target_type'])?> #<?=e($r['target_id'])?></td><td><?=e($r['details'])?></td></tr><?php endforeach;?></table></div><?php page_footer();?>
